INSERT INTO niaoleixinxi (id, mingcheng, keshu, guojiadengji, tupian, tezheng, shenghuoxixing, jianjie, clicknum, discussnum, storeupnum) VALUES (1, '旅鸫', '鸫科', '常见', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/97/American_robin_%2871307%29.jpg/960px-American_robin_%2871307%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', '体型适中，羽色鲜明，易于辨识', '常见于林地、湿地与城市绿地，善鸣唱', '旅鸫是北美最常见的鸫科鸟类之一，胸腹橙红、背部灰褐，鸣声清脆多变，常在清晨与黄昏鸣唱。', 57, 0, 0);
INSERT INTO niaoleixinxi (id, mingcheng, keshu, guojiadengji, tupian, tezheng, shenghuoxixing, jianjie, clicknum, discussnum, storeupnum) VALUES (2, '比氏苇鹪鹩', '鹪鹩科', '常见', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/41/Bewick%27s_wren.jpg/960px-Bewick%27s_wren.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', '体型适中，羽色鲜明，易于辨识', '常见于林地、湿地与城市绿地，善鸣唱', '比氏苇鹪鹩体型小巧，尾羽上翘，鸣声高亢而富有穿透力，常栖息于灌丛与溪流附近。', 64, 0, 0);
INSERT INTO niaoleixinxi (id, mingcheng, keshu, guojiadengji, tupian, tezheng, shenghuoxixing, jianjie, clicknum, discussnum, storeupnum) VALUES (3, '北美红雀', '雀科', '常见', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/89/Northern_Cardinal_%28Cardinalis_cardinalis%29.jpg/960px-Northern_Cardinal_%28Cardinalis_cardinalis%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', '体型适中，羽色鲜明，易于辨识', '常见于林地、湿地与城市绿地，善鸣唱', '北美红雀雄鸟通体鲜红，头顶有醒目冠羽，鸣声洪亮如口哨，是美国多个州的州鸟。', 71, 0, 0);
INSERT INTO niaoleixinxi (id, mingcheng, keshu, guojiadengji, tupian, tezheng, shenghuoxixing, jianjie, clicknum, discussnum, storeupnum) VALUES (4, '小嘲鸫', '鸫科', '常见', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ec/Northern_Mockingbird_%28Mimus_polyglottos%29.jpg/960px-Northern_Mockingbird_%28Mimus_polyglottos%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', '体型适中，羽色鲜明，易于辨识', '常见于林地、湿地与城市绿地，善鸣唱', '小嘲鸫以善于模仿其他鸟类与环境声音著称，鸣唱婉转多变，可连续模仿数十种声音。', 78, 0, 0);
INSERT INTO niaoleixinxi (id, mingcheng, keshu, guojiadengji, tupian, tezheng, shenghuoxixing, jianjie, clicknum, discussnum, storeupnum) VALUES (5, '歌带鹀', '鹀科', '常见', 'https://upload.wikimedia.org/wikipedia/commons/c/c1/Song_Sparrow_%28Melospiza_melodia%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled', '体型适中，羽色鲜明，易于辨识', '常见于林地、湿地与城市绿地，善鸣唱', '歌带鹀胸有褐色条纹，鸣唱开头常有清晰的音符重复，是北美广泛分布的鸣禽。', 85, 0, 0);
INSERT INTO niaoleixinxi (id, mingcheng, keshu, guojiadengji, tupian, tezheng, shenghuoxixing, jianjie, clicknum, discussnum, storeupnum) VALUES (6, '苍鹭', '鹭科', '常见', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b8/Grey_Heron_%28Ardea_cinerea%29.jpg/960px-Grey_Heron_%28Ardea_cinerea%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', '体型适中，羽色鲜明，易于辨识', '常见于林地、湿地与城市绿地，善鸣唱', '苍鹭是大型涉禽，体羽灰白，颈长腿长，常在浅水静立守候捕鱼，广泛分布于欧亚大陆。', 92, 0, 0);
INSERT INTO niaoleixinxi (id, mingcheng, keshu, guojiadengji, tupian, tezheng, shenghuoxixing, jianjie, clicknum, discussnum, storeupnum) VALUES (7, '大天鹅', '鸭科', '常见', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/df/Whooper_Swan_%28Cygnus_cygnus%29.jpg/960px-Whooper_Swan_%28Cygnus_cygnus%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', '体型适中，羽色鲜明，易于辨识', '常见于林地、湿地与城市绿地，善鸣唱', '大天鹅通体洁白，喙基有黄色斑块，冬季在我国长江流域及以北地区越冬，是国家二级保护动物。', 99, 0, 0);
INSERT INTO niaoleixinxi (id, mingcheng, keshu, guojiadengji, tupian, tezheng, shenghuoxixing, jianjie, clicknum, discussnum, storeupnum) VALUES (8, '凤头麦鸡', '鸻科', '常见', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bd/Northern_Lapwing_%28Vanellus_vanellus%29.jpg/960px-Northern_Lapwing_%28Vanellus_vanellus%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', '体型适中，羽色鲜明，易于辨识', '常见于林地、湿地与城市绿地，善鸣唱', '凤头麦鸡头顶有细长羽冠，飞行姿态优雅，是欧亚大陆常见的鸻类。', 106, 0, 0);
INSERT INTO niaoleixinxi (id, mingcheng, keshu, guojiadengji, tupian, tezheng, shenghuoxixing, jianjie, clicknum, discussnum, storeupnum) VALUES (9, '黑翅长脚鹬', '鹬科', '常见', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fa/Black-winged_Stilt_%28Himantopus_himantopus%29.jpg/960px-Black-winged_Stilt_%28Himantopus_himantopus%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', '体型适中，羽色鲜明，易于辨识', '常见于林地、湿地与城市绿地，善鸣唱', '黑翅长脚鹬有粉红色的长腿，黑白分明的体羽，行动轻盈，常群栖于浅水滩涂。', 113, 0, 0);
INSERT INTO niaoleixinxi (id, mingcheng, keshu, guojiadengji, tupian, tezheng, shenghuoxixing, jianjie, clicknum, discussnum, storeupnum) VALUES (10, '红脚鹬', '鹬科', '常见', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bb/Common_Redshank_%28Tringa_totanus%29.jpg/960px-Common_Redshank_%28Tringa_totanus%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', '体型适中，羽色鲜明，易于辨识', '常见于林地、湿地与城市绿地，善鸣唱', '红脚鹬腿脚橙红，繁殖期鸣声急促，是湿地滩涂常见的鹬类。', 120, 0, 0);
INSERT INTO niaoleixinxi (id, mingcheng, keshu, guojiadengji, tupian, tezheng, shenghuoxixing, jianjie, clicknum, discussnum, storeupnum) VALUES (11, '林鹬', '鹬科', '常见', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5e/Wood_Sandpiper_%28Tringa_glareola%29.jpg/960px-Wood_Sandpiper_%28Tringa_glareola%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', '体型适中，羽色鲜明，易于辨识', '常见于林地、湿地与城市绿地，善鸣唱', '林鹬体型纤细，背部有白色斑点，迁徙期广泛见于内陆水塘与稻田。', 127, 0, 0);
INSERT INTO niaoleixinxi (id, mingcheng, keshu, guojiadengji, tupian, tezheng, shenghuoxixing, jianjie, clicknum, discussnum, storeupnum) VALUES (12, '绿头鸭', '鸭科', '常见', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/23/Mallard_%28Anas_platyrhynchos%29.jpg/960px-Mallard_%28Anas_platyrhynchos%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', '体型适中，羽色鲜明，易于辨识', '常见于林地、湿地与城市绿地，善鸣唱', '绿头鸭雄鸟头部辉绿，颈有白环，是家鸭的祖先，也是北半球最常见的野鸭。', 134, 0, 0);
INSERT INTO niaoleixinxi (id, mingcheng, keshu, guojiadengji, tupian, tezheng, shenghuoxixing, jianjie, clicknum, discussnum, storeupnum) VALUES (13, '麻雀', '燕雀科', '常见', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/70/Tree_Sparrow_%28Passer_montanus%29.jpg/960px-Tree_Sparrow_%28Passer_montanus%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', '体型适中，羽色鲜明，易于辨识', '常见于林地、湿地与城市绿地，善鸣唱', '麻雀是最常见的伴人鸟类之一，集群活动于城镇与农田，取食谷物与昆虫。', 141, 0, 0);
INSERT INTO niaoleixinxi (id, mingcheng, keshu, guojiadengji, tupian, tezheng, shenghuoxixing, jianjie, clicknum, discussnum, storeupnum) VALUES (14, '普通鸬鹚', '鸬鹚科', '常见', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/68/Phalacrocorax_carbo_Vic.jpg/960px-Phalacrocorax_carbo_Vic.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', '体型适中，羽色鲜明，易于辨识', '常见于林地、湿地与城市绿地，善鸣唱', '普通鸬鹚通体近黑，善潜水捕鱼，常展开翅膀晾晒羽毛，广泛分布于淡水与沿海水域。', 148, 0, 0);
INSERT INTO niaoleixinxi (id, mingcheng, keshu, guojiadengji, tupian, tezheng, shenghuoxixing, jianjie, clicknum, discussnum, storeupnum) VALUES (15, '雉鸡', '雉科', '常见', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d7/Phasianus_colchicus_2_tom_%28Lukasz_Lukasik%29.jpg/960px-Phasianus_colchicus_2_tom_%28Lukasz_Lukasik%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', '体型适中，羽色鲜明，易于辨识', '常见于林地、湿地与城市绿地，善鸣唱', '雉鸡雄鸟羽色华丽，尾羽修长，是我国重要的陆禽之一。', 155, 0, 0);
INSERT INTO niaoleixinxi (id, mingcheng, keshu, guojiadengji, tupian, tezheng, shenghuoxixing, jianjie, clicknum, discussnum, storeupnum) VALUES (16, '白头鹎', '鹎科', '常见', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/26/Light-vented_Bulbul_%28Pycnonotus_sinensis%29.jpg/960px-Light-vented_Bulbul_%28Pycnonotus_sinensis%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', '体型适中，羽色鲜明，易于辨识', '常见于林地、湿地与城市绿地，善鸣唱', '白头鹎头顶后部白色，鸣声清脆婉转，是我国南方城市园林最常见的鸣禽。', 162, 0, 0);
INSERT INTO niaoleixinxi (id, mingcheng, keshu, guojiadengji, tupian, tezheng, shenghuoxixing, jianjie, clicknum, discussnum, storeupnum) VALUES (17, '珠颈斑鸠', '鸠鸽科', '常见', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6d/Spotted_dove_%28Spilopelia_chinensis_suratensis%29.jpg/960px-Spotted_dove_%28Spilopelia_chinensis_suratensis%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', '体型适中，羽色鲜明，易于辨识', '常见于林地、湿地与城市绿地，善鸣唱', '珠颈斑鸠颈侧有黑白相间的珠状斑纹，鸣声低沉重复，常见于城市绿地。', 169, 0, 0);
INSERT INTO niaoleixinxi (id, mingcheng, keshu, guojiadengji, tupian, tezheng, shenghuoxixing, jianjie, clicknum, discussnum, storeupnum) VALUES (18, '乌鸫', '鸫科', '常见', 'https://upload.wikimedia.org/wikipedia/commons/7/76/Common_Blackbird_%28Turdus_merula%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled', '体型适中，羽色鲜明，易于辨识', '常见于林地、湿地与城市绿地，善鸣唱', '乌鸫雄鸟通体乌黑、喙橙黄，鸣唱婉转动听，是我国常见的鸣禽。', 176, 0, 0);
INSERT INTO niaoleixinxi (id, mingcheng, keshu, guojiadengji, tupian, tezheng, shenghuoxixing, jianjie, clicknum, discussnum, storeupnum) VALUES (19, '喜鹊', '鸦科', '常见', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/00/Pica_pica_-England-8.jpg/960px-Pica_pica_-England-8.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', '体型适中，羽色鲜明，易于辨识', '常见于林地、湿地与城市绿地，善鸣唱', '喜鹊黑白相间，尾长，常在村庄与城市边缘营巢，民间视为吉祥之鸟。', 183, 0, 0);
INSERT INTO niaoleixinxi (id, mingcheng, keshu, guojiadengji, tupian, tezheng, shenghuoxixing, jianjie, clicknum, discussnum, storeupnum) VALUES (20, '大山雀', '雀科', '常见', 'https://upload.wikimedia.org/wikipedia/commons/3/34/Great_Tit_%28Parus_major%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled', '体型适中，羽色鲜明，易于辨识', '常见于林地、湿地与城市绿地，善鸣唱', '大山雀头黑颊白，胸有黑色纵纹，鸣声多变，常见于林地与公园。', 190, 0, 0);
